update public.site_pages set
  blocks_draft = $j$[{"id": "who", "type": "rich_text", "props": {"label": "Who it's for", "heading": "Every kid plays.", "width": "narrow", "html": "<p>Whether your child is picking up a ball for the first time or has played for years, there's a spot for them in the ALL CAN League.</p><p>Players attend an evaluation session first. From there we build balanced teams, play every week and learn the game in a fun, welcoming, professionally run environment. All skill levels are welcome.</p>"}}, {"id": "why", "type": "steps", "props": {"label": "Why it works", "heading": "Built so every player gets better and has fun.", "items": [{"title": "No cuts.", "body": "Every player who registers gets a spot. First time with a ball or years in, there's a place for them."}, {"title": "Balanced teams.", "body": "Players are evaluated first, then placed on even teams, so games stay close and competitive."}, {"title": "Professionally run.", "body": "A fun, welcoming, professionally run environment where players learn the game every week."}, {"title": "Kit included.", "body": "A reversible ALL CAN jersey and shorts for every player, plus a welcome package for new members."}]}}, {"id": "how", "type": "steps", "props": {"label": "How it works", "heading": "From sign-up to Championship Day.", "items": [{"title": "Register.", "body": "Choose your location under Where it runs and register for the season."}, {"title": "Evaluation.", "body": "Every player attends an evaluation session first."}, {"title": "Balanced teams.", "body": "We build even teams from the evaluations, so every game is a real game."}, {"title": "Play every week.", "body": "Skills and a game every week in a fun, welcoming, professionally run environment."}, {"title": "Playoffs.", "body": "The season ends with playoffs and a Championship Day with prizes."}]}}, {"id": "included", "type": "checklist", "props": {"label": "What's included", "heading": "Everything your player gets.", "intro": "Every registration includes:", "items": [{"text": "An evaluation session and placement on a balanced team"}, {"text": "Skills and a game every week"}, {"text": "Reversible ALL CAN jersey and shorts"}, {"text": "Welcome package for new members: backpack, socks and a sticker pack"}, {"text": "Playoffs and championships"}, {"text": "Photo day"}], "imageUrl": "", "imageAlt": "", "caption": "", "ctaLabel": "", "ctaHref": ""}}, {"id": "faq", "type": "faq", "props": {"label": "Questions", "openFirst": true, "items": [{"q": "How do I register?", "a": "Pick your location under Where it runs, then press Register on that location's page.", "note": ""}, {"q": "My child has never played. Is that okay?", "a": "Yes. Everyone starts with an evaluation session and we build balanced teams from there. Beginners and experienced players both have a place.", "note": ""}, {"q": "What if my child isn't very good yet?", "a": "That is exactly who the league is for. There are no cuts: every player gets a spot, and the evaluation is only there to build balanced teams. Players learn the game every week.", "note": ""}, {"q": "What is the refund policy?", "a": "The refund and cancellation policy is [TBC].", "note": ""}, {"q": "Who do I contact?", "a": "Email info@athleteinstitute.ca, or use Ask ALL CAN at the top of the page.", "note": ""}]}}]$j$::jsonb,
