"items": [{"text": "An evaluation session and placement on a balanced team"}, {"text": "Skills and a game every week"}, {"text": "Reversible ALL CAN jersey and shorts"}, {"text": "Welcome package for new members: backpack, socks and a sticker pack"}, {"text": "Playoffs and championships"}, {"text": "Photo day"}], "imageUrl": "", "imageAlt": "", "caption": "", "ctaLabel": "", "ctaHref": ""}}, {"id": "faq", "type": "faq", "props": {"label": "Questions", "openFirst": true, "items": [{"q": "How do I register?", "a": "Pick your location under Where it runs, then press Register on that location's page.", "note": ""}, {"q": "My child has never played. Is that okay?", "a": "Yes. Everyone starts with an evaluation session and we build balanced teams from there. Beginners and experienced players both have a place.", "note": ""}, {"q": "What if my child isn't very good yet?", "a": "That is exactly who the league is for. There are no cuts: every player gets a spot, and the evaluation is only there to build balanced teams. Players learn the game every week.", "note": ""}, {"q": "What is the refund policy?", "a": "The refund and cancellation policy is [TBC].", "note": ""}, {"q": "Who do I contact?", "a": "Email info@athleteinstitute.ca, or use Ask ALL CAN at the top of the page.", "note": ""}]}}]$j$::jsonb,
